"use client";

import React, { useState, useMemo, useRef } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { TfiClose } from "react-icons/tfi";
import { useSearchData } from "./SearchOverlay.hooks";

// Sub-components
import { SearchInput } from "./components/SearchInput";
import { RecentSearches } from "./components/RecentSearches";
import { QuickDiscovery } from "./components/QuickDiscovery";

export const SearchOverlay: React.FC<{
  isSearchOpen: boolean;
  setIsSearchOpen: (v: boolean) => void;
}> = ({ isSearchOpen, setIsSearchOpen }) => {
  const [query, setQuery] = useState("");
  const {
    history,
    allSuggestions,
    saveSearch,
    removeHistoryItem,
  } = useSearchData(10);

  // Memoized Logic
  const filteredHistory = useMemo(() => {
    const list = query.trim()
      ? history.filter((item) =>
          item.toLowerCase().includes(query.toLowerCase())
        )
      : history;
    return list.slice(0, 10);
  }, [query, history]);

  const filteredSuggestions = useMemo(() => {
    if (query.trim().length === 0) return [];
    return allSuggestions
      .filter((item) => item.label.toLowerCase().includes(query.toLowerCase()))
      .slice(0, 8);
  }, [query, allSuggestions]);

  return (
    <AnimatePresence>
      {isSearchOpen && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-[10000] bg-background backdrop-blur-3xl flex flex-col pt-8 px-6 overflow-y-auto pb-20"
        >
          <button
            onClick={() => setIsSearchOpen(false)}
            className="absolute top-4 right-4 p-3 text-foreground hover:bg-white/5 rounded-full transition-colors"
          >
            <TfiClose className="text-2xl" />
          </button>

          <div className="w-full max-w-5xl mx-auto">
            <SearchInput
              query={query}
              setQuery={setQuery}
              onSave={saveSearch}
            />

            {(filteredHistory.length > 0 || filteredSuggestions.length > 0) && (
              <div className="grid md:grid-cols-2 gap-x-16 gap-y-6 mt-10 transition-all">
                <RecentSearches
                  items={filteredHistory}
                  query={query}
                  setQuery={setQuery}
                  onRemove={removeHistoryItem}
                />

                <QuickDiscovery
                  items={filteredSuggestions}
                  query={query}
                  setQuery={setQuery}
                  onSave={saveSearch}
                />
              </div>
            )}
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};
